 */
public class FDistribution_getNumericalMean_TriageGen2Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testGetNumericalMean_LargeDenominator() throws NotStrictlyPositiveException {
        // Testing branch with large value to ensure stability
        // denominatorDF = 102.0
        // Expected: 102 / (102 - 2) = 102 / 100 = 1.02
        double numeratorDF = 10.0;
        double denominatorDF = 102.0;
        FDistribution distribution = new FDistribution(numeratorDF, denominatorDF);

        double expected = 1.02;
        double actual = distribution.getNumericalMean();

        assertEquals("Mean calculation failed for large denominatorDF", 
                     expected, actual, EPSILON);
    }


}

